  // are sheltered and glassy: keep spray to a rare, small lap.
  get seaState() { return this._marina ? 0.15 : 1; }

  // Sky colours for other modules (e.g. UI tint, character rim light). Linear THREE.Colors — do not mutate.
  getSkyColors() {
    const U = this.U;
