  // pilings / dock kit / moored boats / foam field for the current footprint + mode
  _rebuildDock() {
    const reusable=new Map((this.moored||[]).map(m=>[m.spec.kind,m.mesh]));
    const retained=new Set(reusable.values());
    const old = [this.pilings, this.dockProps, ...retained];
    const materials = new Set();
    const addMat = (m) => {
      if (!m) return;
