export const FACE_BONES = { head: 4, eyeL: 19, eyeR: 20 };

/** Mask (Inkling eye mask) signed distance in the head's (az, el): > 0 inside. Same shape as the skin shader's pigment.
 *  Splatoon 3 goggle: one band between a top and a bottom edge, closed by a rounded cap past the outer corner.
 *  Top edge: over each eye it follows the upper lid line a thin margin above it (the arch is fitted to the lid edge of
 *  this eye shape: baseline from the inner to the outer corner plus a skewed arch), and toward the middle it blends
 *  into one smooth line down to the low middle of the nose bridge. Bottom edge: fuller under the eyes, rising steeply
 *  to a thin bridge between them and toward the outer corner — a single even polynomial in az, kept just under the
 *  lower lid's inner wall everywhere so nothing breaks the line. */
