    const w = list[i].weight;
    if (!(w >= 0) || !Number.isFinite(w)) return false;
    sum += w;
    if (a < 0 || w > list[a].weight) { b = a; a = i; }
    else if (b < 0 || w > list[b].weight) b = i;
  }
  if (b < 0 || !Number.isFinite(sum)) return false;
